SELECT percentile_cont(0.25) within GROUP (ORDER BY value) AS p25, percentile_cont(0.75) within GROUP (ORDER BY value) AS p75, percentile_cont(0.50) within GROUP (ORDER BY value) AS p50, MIN(value) AS min_value, MAX(value) AS max_value FROM labevents WHERE subject_id = 100001 AND hadm_id IN (SELECT hadm_id FROM admissions WHERE subject_id = 100001 AND (icd9_code = '42210000' OR icd9_code = '42220000') AND (age BETWEEN 82 AND 92)) AND value > 0.01;